namespace PesajeFaeneo.Tests.Utilidades.Importacion;

internal static class ArchivosDbfDePrueba
{
    private const string Ganaderos850Base64 =
        "";

    private const string PesajesVfp1252Base64 =
        "";

    public static byte[] Ganaderos850 { get; } = Convert.FromBase64String(Ganaderos850Base64);
    public static byte[] PesajesVfp1252 { get; } = Convert.FromBase64String(PesajesVfp1252Base64);

    static ArchivosDbfDePrueba()
    {
        if (Ganaderos850.Length != 446)
        {
            throw new InvalidOperationException($"Ganaderos850 debería medir 446 bytes pero mide {Ganaderos850.Length}");
        }

        if (PesajesVfp1252.Length != 594)
        {
            throw new InvalidOperationException($"PesajesVfp1252 debería medir 594 bytes pero mide {PesajesVfp1252.Length}");
        }
    }
}
